#include <stdio.h>
/* ex06：位示图——用 1 个 bit 表示 1 个块是否空闲
 * 必考换算：给定块号 b（从 0 开始），求所在字号(第几个字)与位号(字内第几位)。
 *   字号 = b / 字长     位号 = b % 字长
 *   字数 = 总块数 / 字长（向上取整）*/
int main(void) {
    long nblocks = 10000;      /* 1 万个块 */
    int word_bits = 32;        /* 每字 32 位 */
    long words = (nblocks + word_bits - 1) / word_bits;
    long bytes = words * 4;

    printf("总块数=%ld 字长=%d 位 -> 需要 %ld 个字（%ld 字节 = %.2f KB）\n",
           nblocks, word_bits, words, bytes, bytes / 1024.0);
    printf("------------------------------------------------------\n");
    printf("%-10s %-10s %-10s %s\n", "块号", "字号", "位号", "定位方式");
    long probe[] = {0, 1, 31, 32, 33, 9999};
    for (int i = 0; i < 6; i++) {
        long b = probe[i];
        printf("%-10ld %-10ld %-10ld 第 %ld 个字的第 %ld 位\n",
               b, b / word_bits, b % word_bits, b / word_bits, b % word_bits);
    }
    printf("------------------------------------------------------\n");
    /* 假设 0 表示空闲，统计空闲块数 */
    unsigned int map[4] = {0xFFFFFFFEu, 0xFFFFFFFFu, 0x0000FFFFu, 0xFFFFFFFFu};
    long free_cnt = 0;
    for (long w = 0; w < 4 && w < words; w++)
        for (int b = 0; b < word_bits; b++)
            if ((map[w] >> b) & 1u) free_cnt++;
    printf("示例位示图前 4 个字中，空闲块数 = %ld（方案：1=空闲）\n", free_cnt);
    printf("结论: 位示图占用空间极小（1 万块只要 %.2f KB）、可快速找连续空闲块；\n", bytes / 1024.0);
    printf("      缺点是「整张图要常驻内存」，超大磁盘要用成组链接或 B 树。\n");
    return 0;
}
